 import requests
import json

def create_post(post_data):
    headers = {
        'Authorization': 'Bearer ' + post_data['access_token']
    }
    url = 'https://api.twitter.com/1.1/statuses/update.json'
    response = requests.post(url, headers=headers, data=post_data)
    return response.json()

def like_post(post_id, access_token):
    headers = {
        'Authorization': 'Bearer ' + access_token
    }
    url = 'https://api.twitter.com/1.1/favorites/create.json'
    data = {
        'id': post_id
    }
    response = requests.post(url, headers=headers, data=data)
    return response.json()

def retweet_post(post_id, access_token):
    headers = {
        'Authorization': 'Bearer ' + access_token
    }
    url = 'https://api.twitter.com/1.1/statuses/retweet/{}'.format(post_id)
    response = requests.post(url, headers=headers)
    return response.json()

def follow_user(user_id, access_token):
    headers = {
        'Authorization': 'Bearer ' + access_token
    }
    url = 'https://api.twitter.com/1.1/friendships/create.json'
    data = {
        'user_id': user_id
    }
    response = requests.post(url, headers=headers, data=data)
    return response.json()

